mapper.select:
SELECT id, room, floor, seat_no, status FROM seat

    room = #{room}
    AND floor = #{floor}

ORDER BY room, floor, seat_no, id

SELECT id, start_time, end_time FROM slot
WHERE start_time >= #{from} AND start_time < #{until}
ORDER BY start_time

SELECT id, room, floor, seat_no, status FROM seat

    room = #{room}
    AND floor = #{floor}
    AND status = #{status}

ORDER BY room, floor, seat_no, id
